package com.cattlefarm.admin.breeding;
import cn.dev33.satoken.stp.StpUtil;import com.baomidou.mybatisplus.core.toolkit.IdWorker;import com.cattlefarm.admin.auth.service.AuthService;import com.cattlefarm.admin.common.DataConflictException;import com.cattlefarm.admin.scope.DataScopeService;import org.springframework.dao.EmptyResultDataAccessException;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.util.StringUtils;
import java.time.*;import java.util.*;import com.cattlefarm.admin.task.TaskService;
@Service
public class BreedingService{
 private final JdbcTemplate jdbc;private final AuthService auth;private final TaskService tasks;private final DataScopeService scope;public BreedingService(JdbcTemplate jdbc,AuthService auth,TaskService tasks,DataScopeService scope){this.jdbc=jdbc;this.auth=auth;this.tasks=tasks;this.scope=scope;}
 public List<BreedingDtos.EventItem>events(String cattleId){long farm=auth.currentFarmId();Long cid=StringUtils.hasText(cattleId)?parse(cattleId,"牛只"):null;return jdbc.query("""
  SELECT e.business_id,e.cattle_id,c.ear_tag_no,e.event_date,e.event_type,e.summary,c.breeding_status FROM cattle_event e JOIN cattle c ON c.cattle_id=e.cattle_id AND c.farm_id=e.farm_id WHERE e.farm_id=? AND e.is_void=0 AND e.event_type IN('ESTRUS_RECORDED','CATTLE_BRED','PREGNANCY_CHECKED','CALVING_RECORDED') AND (? IS NULL OR e.cattle_id=?) ORDER BY e.event_date DESC
  """,(rs,row)->new BreedingDtos.EventItem(Long.toString(rs.getLong(1)),Long.toString(rs.getLong(2)),rs.getString(3),rs.getTimestamp(4).toLocalDateTime(),rs.getString(5),rs.getString(6),rs.getString(7)),farm,cid,cid).stream().filter(x->scope.unrestricted()||scope.canAccessCattle(Long.parseLong(x.cattleId()))).toList();}
 public List<BreedingDtos.HeatItem>heats(String cattleId){long farm=auth.currentFarmId();Long cid=StringUtils.hasText(cattleId)?parse(cattleId,"牛只"):null;return jdbc.query("SELECT e.*,c.ear_tag_no,u.real_name FROM estrus_record e JOIN cattle c ON c.cattle_id=e.cattle_id AND c.farm_id=e.farm_id LEFT JOIN sys_user u ON u.user_id=e.recorder_id WHERE e.farm_id=? AND e.is_void=0 AND (? IS NULL OR e.cattle_id=?) ORDER BY e.estrus_time DESC",(r,n)->new BreedingDtos.HeatItem(Long.toString(r.getLong("estrus_id")),Long.toString(r.getLong("cattle_id")),r.getString("ear_tag_no"),r.getTimestamp("estrus_time").toLocalDateTime(),r.getString("symptoms"),r.getString("suggestion"),r.getString("real_name"),r.getInt("version")),farm,cid,cid).stream().filter(x->scope.unrestricted()||scope.canAccessCattle(Long.parseLong(x.cattleId()))).toList();}
 public List<BreedingDtos.InseminationItem>inseminations(String cattleId){long farm=auth.currentFarmId();Long cid=StringUtils.hasText(cattleId)?parse(cattleId,"牛只"):null;return jdbc.query("SELECT b.*,c.ear_tag_no,u.real_name FROM breeding_record b JOIN cattle c ON c.cattle_id=b.cattle_id AND c.farm_id=b.farm_id LEFT JOIN sys_user u ON u.user_id=b.operator_id WHERE b.farm_id=? AND b.is_void=0 AND (? IS NULL OR b.cattle_id=?) ORDER BY b.breeding_date DESC",(r,n)->new BreedingDtos.InseminationItem(Long.toString(r.getLong("breeding_id")),Long.toString(r.getLong("cattle_id")),r.getString("ear_tag_no"),r.getTimestamp("breeding_date").toLocalDateTime(),r.getString("breeding_method"),r.getString("semen_or_bull"),r.getInt("breeding_times"),r.getString("real_name"),r.getString("remark"),r.getInt("version")),farm,cid,cid).stream().filter(x->scope.unrestricted()||scope.canAccessCattle(Long.parseLong(x.cattleId()))).toList();}
 public List<BreedingDtos.PregnancyItem>pregnancyChecks(String cattleId){long farm=auth.currentFarmId();Long cid=StringUtils.hasText(cattleId)?parse(cattleId,"牛只"):null;return jdbc.query("SELECT p.*,c.ear_tag_no,u.real_name FROM pregnancy_check p JOIN cattle c ON c.cattle_id=p.cattle_id AND c.farm_id=p.farm_id LEFT JOIN sys_user u ON u.user_id=p.checker_id WHERE p.farm_id=? AND p.is_void=0 AND (? IS NULL OR p.cattle_id=?) ORDER BY p.check_date DESC",(r,n)->new BreedingDtos.PregnancyItem(Long.toString(r.getLong("check_id")),Long.toString(r.getLong("cattle_id")),r.getString("ear_tag_no"),r.getObject("breeding_id")==null?null:r.getObject("breeding_id").toString(),r.getTimestamp("check_date").toLocalDateTime(),r.getString("check_result"),r.getDate("expected_calving_date")==null?null:r.getDate("expected_calving_date").toLocalDate(),r.getString("real_name"),r.getString("remark"),r.getInt("version")),farm,cid,cid).stream().filter(x->scope.unrestricted()||scope.canAccessCattle(Long.parseLong(x.cattleId()))).toList();}
 public List<BreedingDtos.CalvingItem>calvings(String cattleId){long farm=auth.currentFarmId();Long cid=StringUtils.hasText(cattleId)?parse(cattleId,"母牛"):null;return jdbc.query("SELECT v.*,c.ear_tag_no,u.real_name FROM calving_record v JOIN cattle c ON c.cattle_id=v.dam_cattle_id AND c.farm_id=v.farm_id LEFT JOIN sys_user u ON u.user_id=v.operator_id WHERE v.farm_id=? AND v.is_void=0 AND (? IS NULL OR v.dam_cattle_id=?) ORDER BY v.calving_date DESC",(r,n)->new BreedingDtos.CalvingItem(Long.toString(r.getLong("calving_id")),Long.toString(r.getLong("dam_cattle_id")),r.getString("ear_tag_no"),r.getObject("pregnancy_check_id")==null?null:r.getObject("pregnancy_check_id").toString(),r.getTimestamp("calving_date").toLocalDateTime(),r.getString("difficulty_level"),r.getInt("calf_count"),r.getInt("alive_count"),r.getString("dam_condition"),r.getString("real_name"),r.getString("remark"),calfIds(farm,r.getLong("calving_id")),r.getInt("version")),farm,cid,cid).stream().filter(x->scope.unrestricted()||scope.canAccessCattle(Long.parseLong(x.damCattleId()))).toList();}
 public List<BreedingDtos.DueCow>dueCows(int days){if(days<0||days>365)throw new DataConflictException("待产查询天数必须在 0 到 365 之间");long farm=auth.currentFarmId();return jdbc.query("""
  SELECT c.cattle_id,c.ear_tag_no,c.name,b.barn_name,h.herd_name,p.check_id,p.expected_calving_date,c.breeding_status
  FROM cattle c JOIN pregnancy_check p ON p.check_id=(SELECT p2.check_id FROM pregnancy_check p2 WHERE p2.farm_id=c.farm_id AND p2.cattle_id=c.cattle_id AND p2.is_void=0 ORDER BY p2.check_date DESC,p2.created_at DESC LIMIT 1)
  LEFT JOIN barn b ON b.farm_id=c.farm_id AND b.barn_id=c.barn_id LEFT JOIN herd h ON h.farm_id=c.farm_id AND h.herd_id=c.herd_id
  WHERE c.farm_id=? AND c.presence_status='IN_FIELD' AND p.check_result='POSITIVE' AND p.expected_calving_date IS NOT NULL
    AND p.expected_calving_date<=DATE_ADD(CURDATE(),INTERVAL ? DAY)
    AND NOT EXISTS(SELECT 1 FROM calving_record v WHERE v.farm_id=c.farm_id AND v.dam_cattle_id=c.cattle_id AND v.is_void=0 AND v.calving_date>=p.check_date)
  ORDER BY p.expected_calving_date,c.ear_tag_no
  """,(r,n)->new BreedingDtos.DueCow(Long.toString(r.getLong("cattle_id")),r.getString("ear_tag_no"),r.getString("name"),r.getString("barn_name"),r.getString("herd_name"),Long.toString(r.getLong("check_id")),r.getDate("expected_calving_date").toLocalDate(),java.time.temporal.ChronoUnit.DAYS.between(LocalDate.now(),r.getDate("expected_calving_date").toLocalDate()),r.getString("breeding_status")),farm,days).stream().filter(x->scope.unrestricted()||scope.canAccessCattle(Long.parseLong(x.cattleId()))).toList();}
 @Transactional public BreedingDtos.Result estrus(BreedingDtos.Estrus r,String key){long farm=auth.currentFarmId(),user=StpUtil.getLoginIdAsLong();Long replay=replay(farm,user,key,"/api/v1/breeding/estrus");if(replay!=null)return result("estrus_record","estrus_id",replay,List.of());Cow cow=cow(farm,parse(r.cattleId(),"母牛"),false);long id=IdWorker.getId();idem(farm,user,key,"/api/v1/breeding/estrus",id);jdbc.update("INSERT INTO estrus_record(estrus_id,farm_id,cattle_id,estrus_time,symptoms,suggestion,recorder_id) VALUES (?,?,?,?,?,?,?)",id,farm,cow.id(),r.estrusTime(),r.symptoms(),r.suggestion(),user);if(cow.status()==null)jdbc.update("UPDATE cattle SET breeding_status='WAIT_BREED',updated_by=?,version=version+1 WHERE cattle_id=? AND farm_id=?",user,cow.id(),farm);event(farm,cow.id(),"ESTRUS_RECORDED",r.estrusTime(),"estrus_record",id,"记录发情表现",user);audit(farm,user,"ESTRUS_RECORDED","ESTRUS",id);return result("estrus_record","estrus_id",id,List.of());}
 @Transactional public BreedingDtos.Result breed(BreedingDtos.Breed r,String key){long farm=auth.currentFarmId(),user=StpUtil.getLoginIdAsLong();Long replay=replay(farm,user,key,"/api/v1/breeding/inseminations");if(replay!=null)return result("breeding_record","breeding_id",replay,List.of());Cow cow=cow(farm,parse(r.cattleId(),"母牛"),true);long id=IdWorker.getId();idem(farm,user,key,"/api/v1/breeding/inseminations",id);jdbc.update("INSERT INTO breeding_record(breeding_id,farm_id,cattle_id,breeding_date,breeding_method,semen_or_bull,breeding_times,operator_id,remark) VALUES (?,?,?,?,?,?,?,?,?)",id,farm,cow.id(),r.breedingDate(),r.breedingMethod(),r.semenOrBull().trim(),r.breedingTimes()==null?1:r.breedingTimes(),user,r.remark());updateStatus(farm,cow.id(),"BRED_WAIT_CHECK",user);event(farm,cow.id(),"CATTLE_BRED",r.breedingDate(),"breeding_record",id,"完成配种："+("AI".equals(r.breedingMethod())?"人工授精":"自然交配"),user);LocalDate plan=r.breedingDate().toLocalDate().plusDays(30);tasks.createAutomatic(farm,id,"BREEDING","PREGNANCY_CHECK","母牛 "+cow.earTag()+" 妊检",cow.id(),cow.herdId(),cow.barnId(),plan,plan.plusDays(3),user,"NORMAL");audit(farm,user,"BREEDING_RECORDED","BREEDING",id);return result("breeding_record","breeding_id",id,List.of());}
 @Transactional public BreedingDtos.Result pregnancy(BreedingDtos.Pregnancy r,String key){long farm=auth.currentFarmId(),user=StpUtil.getLoginIdAsLong();Long replay=replay(farm,user,key,"/api/v1/breeding/pregnancy-checks");if(replay!=null)return result("pregnancy_check","check_id",replay,List.of());Cow cow=cow(farm,parse(r.cattleId(),"母牛"),true);Long breedingId=StringUtils.hasText(r.breedingId())?parse(r.breedingId(),"配种记录"):latestBreeding(farm,cow.id());if(breedingId!=null)validateBreeding(farm,cow.id(),breedingId);LocalDate due=r.expectedCalvingDate();if("POSITIVE".equals(r.checkResult())&&due==null){LocalDateTime bred=jdbc.queryForObject("SELECT breeding_date FROM breeding_record WHERE breeding_id=?",LocalDateTime.class,breedingId);due=bred.toLocalDate().plusDays(283);}if("POSITIVE".equals(r.checkResult())&&due==null)throw new DataConflictException("阳性妊检必须提供预计产犊日或关联配种记录");long id=IdWorker.getId();idem(farm,user,key,"/api/v1/breeding/pregnancy-checks",id);jdbc.update("INSERT INTO pregnancy_check(check_id,farm_id,cattle_id,breeding_id,check_date,check_result,expected_calving_date,checker_id,remark) VALUES (?,?,?,?,?,?,?,?,?)",id,farm,cow.id(),breedingId,r.checkDate(),r.checkResult(),due,user,r.remark());String status=switch(r.checkResult()){case"POSITIVE"->"PREGNANT";case"NEGATIVE"->"WAIT_BREED";default->"BRED_WAIT_CHECK";};updateStatus(farm,cow.id(),status,user);event(farm,cow.id(),"PREGNANCY_CHECKED",r.checkDate(),"pregnancy_check",id,"妊检结果："+checkLabel(r.checkResult()),user);if(breedingId!=null)tasks.finishSource(farm,"BREEDING",breedingId,"PREGNANCY_CHECK",checkLabel(r.checkResult()),user,"DONE");if("RECHECK".equals(r.checkResult())){LocalDate plan=r.checkDate().toLocalDate().plusDays(7);tasks.createAutomatic(farm,id,"PREGNANCY_CHECK","PREGNANCY_RECHECK","母牛 "+cow.earTag()+" 妊检复查",cow.id(),cow.herdId(),cow.barnId(),plan,plan.plusDays(3),user,"NORMAL");}else if("POSITIVE".equals(r.checkResult())){LocalDate plan=due.minusDays(15);tasks.createAutomatic(farm,id,"PREGNANCY_CHECK","CALVING_CHECK","母牛 "+cow.earTag()+" 待产检查",cow.id(),cow.herdId(),cow.barnId(),plan,due,user,"IMPORTANT");}audit(farm,user,"PREGNANCY_CHECKED","PREGNANCY_CHECK",id);return result("pregnancy_check","check_id",id,List.of());}
 @Transactional public BreedingDtos.Result calving(BreedingDtos.Calving r,String key){long farm=auth.currentFarmId(),user=StpUtil.getLoginIdAsLong();Long replay=replay(farm,user,key,"/api/v1/breeding/calvings");if(replay!=null)return result("calving_record","calving_id",replay,calfIds(farm,replay));Cow dam=cow(farm,parse(r.damCattleId(),"母牛"),true);if(!List.of("PREGNANT","NEAR_CALVING").contains(dam.status()))throw new DataConflictException("母牛当前不是妊娠或临产状态");List<BreedingDtos.Calf>calves=r.calves()==null?List.of():r.calves();if(calves.size()!=r.aliveCount())throw new DataConflictException("创建犊牛档案数量必须等于存活数量");if(r.aliveCount()>r.calfCount())throw new DataConflictException("存活数量不能大于犊牛总数");for(var calf:calves){if("DEAD".equals(calf.survivalStatus()))throw new DataConflictException("死亡犊牛不创建在场档案");}Long checkId=StringUtils.hasText(r.pregnancyCheckId())?parse(r.pregnancyCheckId(),"妊检记录"):latestPositiveCheck(farm,dam.id());long id=IdWorker.getId();idem(farm,user,key,"/api/v1/breeding/calvings",id);jdbc.update("INSERT INTO calving_record(calving_id,farm_id,dam_cattle_id,pregnancy_check_id,calving_date,difficulty_level,calf_count,alive_count,dam_condition,operator_id,remark) VALUES (?,?,?,?,?,?,?,?,?,?,?)",id,farm,dam.id(),checkId,r.calvingDate(),r.difficultyLevel(),r.calfCount(),r.aliveCount(),r.damCondition(),user,r.remark());List<String>created=new ArrayList<>();int order=1;for(var calf:calves){long calfId=IdWorker.getId();jdbc.update("""
  INSERT INTO cattle(cattle_id,farm_id,ear_tag_no,sex,birth_date,source_type,entry_date,lifecycle_stage,presence_status,health_status,herd_id,barn_id,dam_id,created_by,updated_by,version) VALUES (?,?,?,?,?,'BIRTH',?,'CALF','IN_FIELD','NORMAL',?,?,?,?,?,0)
  """,calfId,farm,calf.earTagNo().trim(),calf.sex(),r.calvingDate().toLocalDate(),r.calvingDate().toLocalDate(),dam.herdId(),dam.barnId(),dam.id(),user,user);jdbc.update("INSERT INTO calving_calf_relation(id,farm_id,calving_id,calf_cattle_id,birth_order,birth_weight,survival_status) VALUES (?,?,?,?,?,?,?)",IdWorker.getId(),farm,id,calfId,order++,calf.birthWeight(),calf.survivalStatus());event(farm,calfId,"CATTLE_CREATED",r.calvingDate(),"calving_record",id,"产犊自动创建犊牛档案，母牛耳号："+dam.earTag(),user);created.add(Long.toString(calfId));}updateStatus(farm,dam.id(),"POSTPARTUM",user);event(farm,dam.id(),"CALVING_RECORDED",r.calvingDate(),"calving_record",id,"完成产犊登记，存活 "+r.aliveCount()+" 头",user);tasks.finishOpenForCattle(farm,"CALVING_CHECK",dam.id(),"已完成产犊登记",user);tasks.finishOpenForCattle(farm,"CALVING_HANDLE",dam.id(),"已完成产犊登记",user);audit(farm,user,"CALVING_RECORDED","CALVING",id);return result("calving_record","calving_id",id,created);}
 private Cow cow(long farm,long id,boolean mature){if(!scope.unrestricted())scope.assertCattle(id);try{Cow c=jdbc.queryForObject("SELECT cattle_id,ear_tag_no,sex,lifecycle_stage,presence_status,breeding_status,herd_id,barn_id FROM cattle WHERE farm_id=? AND cattle_id=?",(rs,row)->new Cow(rs.getLong(1),rs.getString(2),rs.getString(3),rs.getString(4),rs.getString(5),rs.getString(6),(Long)rs.getObject(7),(Long)rs.getObject(8)),farm,id);if(!"FEMALE".equals(c.sex()))throw new DataConflictException("繁育记录只能关联母牛");if(!"IN_FIELD".equals(c.presence()))throw new DataConflictException("已离场母牛不可登记繁育记录");if(mature&&!List.of("RESERVE","COW").contains(c.stage()))throw new DataConflictException("犊牛或育成牛不可执行该繁育操作");return c;}catch(EmptyResultDataAccessException e){throw new DataConflictException("母牛不存在");}}
 private void updateStatus(long farm,long cattle,String status,long user){jdbc.update("UPDATE cattle SET breeding_status=?,updated_by=?,version=version+1 WHERE farm_id=? AND cattle_id=?",status,user,farm,cattle);}private Long latestBreeding(long farm,long cattle){try{return jdbc.queryForObject("SELECT breeding_id FROM breeding_record WHERE farm_id=? AND cattle_id=? AND is_void=0 ORDER BY breeding_date DESC LIMIT 1",Long.class,farm,cattle);}catch(EmptyResultDataAccessException e){return null;}}private Long latestPositiveCheck(long farm,long cattle){try{return jdbc.queryForObject("SELECT check_id FROM pregnancy_check WHERE farm_id=? AND cattle_id=? AND check_result='POSITIVE' AND is_void=0 ORDER BY check_date DESC LIMIT 1",Long.class,farm,cattle);}catch(EmptyResultDataAccessException e){return null;}}private void validateBreeding(long farm,long cattle,long id){Integer n=jdbc.queryForObject("SELECT COUNT(*) FROM breeding_record WHERE farm_id=? AND cattle_id=? AND breeding_id=? AND is_void=0",Integer.class,farm,cattle,id);if(n==null||n==0)throw new DataConflictException("配种记录不属于该母牛");}
 private BreedingDtos.Result result(String table,String pk,long id,List<String>calves){long farm=auth.currentFarmId();Long cattle=jdbc.queryForObject("SELECT "+("calving_record".equals(table)?"dam_cattle_id":"cattle_id")+" FROM "+table+" WHERE "+pk+"=? AND farm_id=?",Long.class,id,farm);String status=jdbc.queryForObject("SELECT breeding_status FROM cattle WHERE cattle_id=? AND farm_id=?",String.class,cattle,farm);return new BreedingDtos.Result(Long.toString(id),Long.toString(cattle),status,calves);}private List<String>calfIds(long farm,long calving){return jdbc.query("SELECT calf_cattle_id FROM calving_calf_relation WHERE farm_id=? AND calving_id=? ORDER BY birth_order",(rs,row)->Long.toString(rs.getLong(1)),farm,calving);}
 private void event(long farm,long cattle,String type,LocalDateTime date,String table,long id,String summary,long user){jdbc.update("INSERT INTO cattle_event(event_id,farm_id,cattle_id,event_type,event_date,business_table,business_id,summary,operator_id,is_void) VALUES (?,?,?,?,?,?,?,?,?,0)",IdWorker.getId(),farm,cattle,type,date,table,id,summary,user);}private void audit(long farm,long user,String action,String type,long id){jdbc.update("INSERT INTO operation_log(operation_log_id,farm_id,user_id,module_code,action_type,business_type,business_id,reason) VALUES (?,?,?,?,?,?,?,'登记繁育业务')",IdWorker.getId(),farm,user,"BREEDING",action,type,id);}private void idem(long farm,long user,String key,String path,long id){jdbc.update("INSERT INTO idempotency_record(farm_id,user_id,idempotency_key,request_path,business_id,expires_at) VALUES (?,?,?,?,?,?)",farm,user,key,path,id,LocalDateTime.now().plusDays(1));}private Long replay(long farm,long user,String key,String path){try{return jdbc.queryForObject("SELECT business_id FROM idempotency_record WHERE farm_id=? AND user_id=? AND idempotency_key=? AND request_path=? AND expires_at>NOW()",Long.class,farm,user,key,path);}catch(EmptyResultDataAccessException e){return null;}}private long parse(String v,String label){try{return Long.parseLong(v);}catch(NumberFormatException e){throw new DataConflictException(label+"编号格式错误");}}private String checkLabel(String v){return switch(v){case"POSITIVE"->"阳性";case"NEGATIVE"->"阴性";default->"待复查";};}private record Cow(long id,String earTag,String sex,String stage,String presence,String status,Long herdId,Long barnId){}
}
